input.command:
cp darksafe/org.go /tmp/org.go.bak
# Mutation 2: commit under lock, then validate (simulates partial/non-atomic apply)
python3 - <<'EOF'
src = open('darksafe/org.go').read()
old = '''	snapshot, err := validatePolicies(policies)
	if err != nil {
		return 0, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	st := s.orgLocked(org)
	if expectedVersion != st.current {
		return 0, fmt.Errorf("%w: expected %d, current is %d", ErrVersionConflict, expectedVersion, st.current)
	}
	return st.commitVersionLocked(org, snapshot, 0, false), nil'''
new = '''	snapshot := append([]Policy(nil), policies...)
	s.mu.Lock()
	defer s.mu.Unlock()
	st := s.orgLocked(org)
	if expectedVersion != st.current {
		return 0, fmt.Errorf("%w: expected %d, current is %d", ErrVersionConflict, expectedVersion, st.current)
	}
	v := st.commitVersionLocked(org, snapshot, 0, false)
	if _, err := validatePolicies(policies); err != nil {
		return 0, err
	}
	return v, nil'''
assert old in src
open('darksafe/org.go','w').write(src.replace(old,new))
EOF
go test ./darksafe/ -run TestFailedBatchPublishChangesNothing 2>&1 | grep -E "FAIL|PASS|want" | head -12
cp /tmp/org.go.bak darksafe/org.go
